import React, { useState } from "react";
import { sendRequest } from "./requests/requests";
import "./App.css";

function App() {
  const [imageFile, setImageFile] = useState(null);
  const [secondImage, setSecondImage] = useState(null);
  const [operation, setOperation] = useState("gray");
  const [params, setParams] = useState({});
  const [resultUrl, setResultUrl] = useState("");
  const [previewUrl, setPreviewUrl] = useState("");
  const [previewSecond, setPreviewSecond] = useState("");

  const handleSubmit = async () => {
    if (!imageFile) {
      alert("Lütfen bir görsel yükleyin.");
      return;
    }

    const data = await sendRequest({
      operation,
      imageFile,
      secondImageFile: secondImage,
      params
    });

    if (data?.url) {
      setResultUrl(data.url);
    } else {
      alert("İşlem başarısız oldu.");
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImageFile(file);
    if (file) setPreviewUrl(URL.createObjectURL(file));
  };

  const handleSecondImageChange = (e) => {
    const file = e.target.files[0];
    setSecondImage(file);
    if (file) setPreviewSecond(URL.createObjectURL(file));
  };

  const renderParams = () => {
    switch (operation) {
      case "binary":
        return <input type="number" placeholder="Threshold" onChange={e => setParams({ threshold: Number(e.target.value) })} />;
      case "rotate":
        return <input type="number" placeholder="Açı" onChange={e => setParams({ angle: Number(e.target.value) })} />;
      case "zoom":
        return <input type="number" step="0.1" placeholder="Ölçek" onChange={e => setParams({ scale: Number(e.target.value) })} />;
      case "contrast":
        return <input type="number" step="0.1" placeholder="Faktör (0-1)" onChange={e => setParams({ factor: Number(e.target.value) })} />;
      case "motion":
      case "median":
        return <input type="number" placeholder="Çekirdek Boyutu" onChange={e => setParams({ kernel_size: Number(e.target.value) })} />;
      case "color":
        return <input type="text" placeholder="Mod (HSV/YUV)" onChange={e => setParams({ mode: e.target.value })} />;
      case "double_threshold":
        return (
          <>
            <input type="number" placeholder="Alt Eşik" onChange={e => setParams(prev => ({ ...prev, low_thresh: Number(e.target.value) }))} />
            <input type="number" placeholder="Üst Eşik" onChange={e => setParams(prev => ({ ...prev, high_thresh: Number(e.target.value) }))} />
          </>
        );
      case "edge":
        return (
          <>
            <input type="number" placeholder="Threshold 1" onChange={e => setParams(prev => ({ ...prev, threshold1: Number(e.target.value) }))} />
            <input type="number" placeholder="Threshold 2" onChange={e => setParams(prev => ({ ...prev, threshold2: Number(e.target.value) }))} />
          </>
        );
      case "crop":
        return (
          <>
            <input type="number" placeholder="X" onChange={e => setParams(prev => ({ ...prev, x: Number(e.target.value) }))} />
            <input type="number" placeholder="Y" onChange={e => setParams(prev => ({ ...prev, y: Number(e.target.value) }))} />
            <input type="number" placeholder="Genişlik" onChange={e => setParams(prev => ({ ...prev, width: Number(e.target.value) }))} />
            <input type="number" placeholder="Yükseklik" onChange={e => setParams(prev => ({ ...prev, height: Number(e.target.value) }))} />
          </>
        );
      case "noise":
        return <input type="number" step="0.01" placeholder="Miktar (0-1)" onChange={e => setParams({ amount: Number(e.target.value) })} />;
      case "denoise":
        return (
          <>
            <select onChange={e => setParams(prev => ({ ...prev, filter_type: e.target.value }))}>
              <option value="mean">Mean</option>
              <option value="median">Median</option>
            </select>
            <input type="number" placeholder="Çekirdek" onChange={e => setParams(prev => ({ ...prev, kernel_size: Number(e.target.value) }))} />
          </>
        );
      case "morphology":
        return (
          <>
            <select onChange={e => setParams(prev => ({ ...prev, morph_op: e.target.value }))}>
              <option value="dilate">Genişlet</option>
              <option value="erode">Aşındır</option>
              <option value="open">Açma</option>
              <option value="close">Kapama</option>
            </select>
            <input type="number" placeholder="Çekirdek" onChange={e => setParams(prev => ({ ...prev, kernel_size: Number(e.target.value) }))} />
          </>
        );
      case "arithmetic":
        return (
          <>
            <input type="file" onChange={handleSecondImageChange} />
            <select onChange={e => setParams({ arithmetic_op: e.target.value })}>
              <option value="subtract">Çıkarma</option>
              <option value="multiply">Çarpma</option>
            </select>
          </>
        );
      default:
        return null;
    }
  };

  return (
    <div className="container">
      <h2>Görüntü İşleme Uygulaması</h2>

      <input type="file" accept="image/*" onChange={handleImageChange} />
      <select onChange={e => {
        setOperation(e.target.value);
        setParams({});
        setSecondImage(null);
        setPreviewSecond("");
        setResultUrl(""); // işlem değişince sonucu sil
      }}>
        <option value="gray">Gri Dönüşüm</option>
        <option value="binary">Binary</option>
        <option value="rotate">Döndürme</option>
        <option value="crop">Kırpma</option>
        <option value="zoom">Yaklaştırma</option>
        <option value="color">Renk Uzayı</option>
        <option value="histogram">Histogram</option>
        <option value="contrast">Kontrast Azalt</option>
        <option value="median">Median</option>
        <option value="double_threshold">Çift Eşik</option>
        <option value="edge">Kenar Bul</option>
        <option value="noise">Gürültü Ekle</option>
        <option value="denoise">Gürültü Temizle</option>
        <option value="motion">Motion Blur</option>
        <option value="morphology">Morfoloji</option>
        <option value="arithmetic">Aritmetik İşlem</option>
      </select>

      {renderParams()}
      <button onClick={handleSubmit}>Uygula</button>

      {/* Görseller */}
      {operation === "arithmetic" ? (
        <div className="row-images">
          {previewUrl && <div><h4>1. Görsel</h4><img src={previewUrl} alt="1. Görsel" /></div>}
          {previewSecond && <div><h4>2. Görsel</h4><img src={previewSecond} alt="2. Görsel" /></div>}
          {resultUrl && (
            <div>
              <h4>Sonuç</h4>
              <img src={resultUrl} alt="Sonuç" />
              <a href={resultUrl} download><button>İndir</button></a>
            </div>
          )}
        </div>
      ) : (
        <>
          {previewUrl && <div><h4>Yüklenen Görsel</h4><img src={previewUrl} alt="Yüklenen" /></div>}
          {resultUrl && (
            <div>
              <h4>İşlem Sonucu</h4>
              <img src={resultUrl} alt="Sonuç" />
              <a href={resultUrl} download><button>İndir</button></a>
            </div>
          )}
        </>
      )}
    </div>
  );
}

export default App;
